\set ON_ERROR_STOP on
begin;
set local search_path=public,extensions;
select no_plan();
insert into auth.users(id,aud,role,email,raw_app_meta_data,raw_user_meta_data) values ('50000000-0000-4000-8000-000000000001','authenticated','authenticated','transfer@example.test','{}','{}'),('50000000-0000-4000-8000-000000000002','authenticated','authenticated','outsider@example.test','{}','{}');
insert into public.platform_operators(user_id) values('50000000-0000-4000-8000-000000000001');
insert into public.workspaces(id,name) values('50000000-0000-4000-8000-000000000011','Transfer');
insert into public.workspace_members(workspace_id,user_id,role) values('50000000-0000-4000-8000-000000000011','50000000-0000-4000-8000-000000000001','owner');
insert into public.marketplace_connections(id,workspace_id,display_name,external_account_id,status) values('50000000-0000-4000-8000-000000000021','50000000-0000-4000-8000-000000000011','Vinted','99','connected');
insert into public.marketplace_account_entries(id,workspace_id,connection_id,kind,external_id,body) values('50000000-0000-4000-8000-000000000031','50000000-0000-4000-8000-000000000011','50000000-0000-4000-8000-000000000021','publication','123',jsonb_build_object('transferSource',jsonb_build_object('title','Jacke','description','Vollständiger Text','photoReferences',jsonb_build_array('https://images1.vinted.net/test.jpg'),'externalAccountId','99','externalId','123','priceCents',1200,'currency','EUR','attributeHints','{}'::jsonb,'observedAt',clock_timestamp())));
insert into public.kleinanzeigen_connections(workspace_id,external_account_id,display_name,account_type,created_by) values('50000000-0000-4000-8000-000000000011','88','Kleinanzeigen','private','50000000-0000-4000-8000-000000000001');
create function pg_temp.source_ref() returns jsonb language sql as $$ select jsonb_build_object('platform','vinted','workspaceId',workspace_id,'connectionId',connection_id,'externalId',external_id,'entryId',id,'fingerprint',encode(extensions.digest(((body->'transferSource')-'observedAt')::text,'sha256'),'hex')) from public.marketplace_account_entries where id='50000000-0000-4000-8000-000000000031'; $$;
create function pg_temp.create_draft(p_source jsonb default pg_temp.source_ref(),p_request uuid default '50000000-0000-4000-8000-000000000041') returns jsonb language sql as $$ select public.kleinanzeigen_create_transfer_draft('50000000-0000-4000-8000-000000000011',(select id from public.kleinanzeigen_connections where external_account_id='88'),p_source,'{"title":"Jacke","description":"Vollständiger Text","priceCents":1200,"currency":"EUR","priceType":"FIXED","shippingType":"pickup","postalCode":null,"categoryId":null,"categoryFields":{},"schemaRevision":null}',p_request); $$;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"50000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select lives_ok($$select pg_temp.create_draft()$$,'Testentwurf angelegt');
select ok(not has_column_privilege('authenticated','public.listings','transfer_images_complete','update'),'Vollständigkeit kann nicht vom Frontend behauptet werden');
select throws_ok($$select public.kleinanzeigen_complete_transfer_images('50000000-0000-4000-8000-000000000011',(select id from public.listings),1,'50000000-0000-4000-8000-000000000001','[]')$$,'42501',null,'Bildabschluss ist servergebunden');
reset role;
create function pg_temp.complete_images(p_revision bigint default 1) returns jsonb language sql security definer as $$select public.kleinanzeigen_complete_transfer_images('50000000-0000-4000-8000-000000000011',(select id from public.listings),p_revision,'50000000-0000-4000-8000-000000000001',jsonb_build_array(jsonb_build_object('storagePath','listings/50000000-0000-4000-8000-000000000011/'||(select id::text from public.listings)||'/0.jpg','fileName','Vinted-1.jpg','sortOrder',0)));$$;
set local role service_role;
select throws_ok($$select pg_temp.complete_images()$$,'22023',null,'Fehlende private Datei blockiert die Vollständigkeit');
reset role;
insert into storage.objects(bucket_id,name,metadata) select 'item-media','listings/50000000-0000-4000-8000-000000000011/'||id::text||'/0.jpg','{"mimetype":"image/jpeg","size":1024}'::jsonb from public.listings;
set local role service_role;
select lives_ok($$select pg_temp.complete_images()$$,'Alle Fotos werden atomar übernommen');
reset role;
select ok((select transfer_images_complete and image_selection_saved from public.listings),'Erst vollständiger Abschluss markiert Bilder als gesichert');
select is((select count(*)::int from public.listing_images),1,'Genau ein Bild angelegt');
select is((select revision::int from public.listings),3,'Bildeinfügen und Vollständigkeit aktualisieren Revision');
set local role service_role;
select throws_ok($$select pg_temp.complete_images()$$,'40001',null,'Wiederholter Abschluss kann die Bildauswahl nicht ersetzen');
reset role;set local role authenticated;
select lives_ok($$update public.listing_images set sort_order=1$$,'Benutzer kann eigene Bildreihenfolge ändern');
reset role;
select is((select revision::int from public.listings),4,'Auch Bildänderung aktualisiert die Entwurfsrevision');
reset role;
update public.marketplace_account_entries set body=jsonb_set(body,'{transferSource,photoReferences}','[]'::jsonb) where external_id='123';
set local role authenticated;
select set_config('test.ka.empty_draft',pg_temp.create_draft(p_request=>'50000000-0000-4000-8000-000000000043')->>'id',true);
reset role;set local role service_role;
select lives_ok($$select public.kleinanzeigen_complete_transfer_images('50000000-0000-4000-8000-000000000011',current_setting('test.ka.empty_draft')::uuid,1,'50000000-0000-4000-8000-000000000001','[]')$$,'Keine Quellfotos sind eine vollstaendig uebernommene leere Auswahl');
reset role;
select ok((select transfer_images_complete and image_selection_saved from public.listings where id=current_setting('test.ka.empty_draft')::uuid),'Leere Quellfotos blockieren spaetere manuelle Bilder nicht dauerhaft');
select is((select count(*)::int from public.listing_images where listing_id=current_setting('test.ka.empty_draft')::uuid),0,'Leerer Abschluss erfindet keine gesicherten Bilder');
select * from finish();rollback;
